import * as A from './academic-year.js';
import * as M from './model.js';
import * as P from './planner.js';
import * as C from './curriculum.js';
import * as PC from './teacher-pc.js';

export const FOCUS={reading:'함께 읽고 표현하기',inquiry:'질문하며 탐구하기',community:'서로 존중하는 학급',autonomy:'스스로 계획하고 실천하기'};
export const EVIDENCE=['관찰·구술','설명 글·활동지','작품·포트폴리오','실기·발표'];
export const AREAS=['자율·자치활동','동아리활동','진로활동'];
const allSubjects=s=>[...M.subjects(s.config.grade),'창체'];
export function deadline(s){let last=s.academic?.start||0;for(let day=s.academic?.start||0;day<M.demoDays(s);day++){if(M.schoolDate(day).getUTCMonth()===2)last=day;else break;}return last;}
export function defaults(s){return {schema:1,draft:{goal:'',support:'',focus:'community',creative:AREAS.map((area,i)=>({area,topic:['함께 정하는 학급 약속','관심을 나누는 독서·탐구 모임','내가 좋아하는 일과 필요한 도움'][i]})),rows:allSubjects(s).map((subject,i)=>({subject,goal:C.design(subject,0,'m0',s.config.grade).goal,method:'m0',room:C.subjectRooms(subject)[0],evidence:EVIDENCE[i%EVIDENCE.length],assessDay:Math.min(M.demoDays(s)-1,Math.max(s.day,14+i)),materials:'학교 공용 교구와 보유 준비물 우선 활용'}))},active:null,revisions:[],notified:{},catchups:[]};}
export const data=s=>s.classCurriculum??=defaults(s);
export const assessmentId=(subject,s)=>'curriculum-assess-'+(s?.academic?s.academic.year+'-'+A.term(s)+'-':'')+subject;
export function assessmentCount(s,subject){return s.students.filter(st=>{const current=row(s,subject),r=st.records.find(r=>r.kind==='performance'&&r.planId===assessmentId(subject,s)&&r.plannedGoal===current?.goal&&r.plannedEvidence===current?.evidence);return r&&r.level!=='미실시';}).length;}
export function sync(s){const d=data(s);if(s.academic&&!s.academic.acknowledged)return d;const due=deadline(s);P.upsert(s,{id:'class-curriculum-march',title:'3월 학급교육과정 수립',day:due,start:980,end:1000,room:'classroom',type:'task',source:'학급업무 · 3월 제출',response:'참석',status:d.active?'완료':'예정'});
 const reminder=!d.active?(s.day>due?'late':s.day>=due-4?'soon':'start'):null;if(reminder&&!d.notified[reminder]){d.notified[reminder]=true;M.addMessage(s,'all','한정우 교감',reminder==='late'?'학급교육과정의 3월 마감이 지났습니다. 지금 확인한 학생 특성을 반영해 보완 제출해 주세요. 실제 제출 날짜로 기록하겠습니다.':reminder==='soon'?'학급교육과정 수립 마감이 다가옵니다. 3월 안에 목표·학생 지원·교과와 창체 계획을 확인하고 제출해 주세요.':'3월 안에 학급교육과정을 수립해 주세요. 학교의 기본 시간표를 바탕으로 우리 반 목표, 학생 지원, 교과·창체 활동과 평가 계획을 정하면 됩니다.',{senderId:'principal',plannerScanned:true});}
 if(d.active)for(const row of d.active.plan.rows.filter(r=>r.subject!=='창체'))P.upsert(s,{id:assessmentId(row.subject,s),title:row.subject+' 수행평가 확인',day:row.assessDay,start:980,end:1000,room:'classroom',type:'task',source:'학급교육과정 · 평가 계획',response:'참석',status:assessmentCount(s,row.subject)===s.students.length?'완료':'예정'});
 for(const c of d.catchups){const result=s.lessonResults.find(r=>r.day===c.target.day&&r.period===c.target.period&&r.subject===c.subject);if(result&&c.status==='planned'){c.status='done';c.completed=M.stamp(s);}else if(c.status==='planned'){const end=A.plannedSchedule(s,c.target.day).find(x=>x.period===c.target.period)?.end;if(c.target.day<s.day||c.target.day===s.day&&s.minute>=end)c.status='missed';}}
 return d;
}
export function saveDraft(s,patch){const d=data(s),p=d.draft;if(typeof patch.goal==='string')p.goal=patch.goal.slice(0,300);if(typeof patch.support==='string')p.support=patch.support.slice(0,500);if(Object.hasOwn(FOCUS,patch.focus))p.focus=patch.focus;if(Array.isArray(patch.creative))p.creative=AREAS.map(area=>({area,topic:String(patch.creative.find(x=>x.area===area)?.topic||'').slice(0,180)}));if(Array.isArray(patch.rows))for(const r of patch.rows){const row=p.rows.find(x=>x.subject===r.subject);if(!row)continue;for(const key of ['goal','materials'])if(typeof r[key]==='string')row[key]=r[key].slice(0,300);if(C.methods(row.subject,true).some(x=>x.id===r.method))row.method=r.method;if(C.subjectRooms(row.subject).includes(r.room))row.room=r.room;if(EVIDENCE.includes(r.evidence))row.evidence=r.evidence;if(Number.isInteger(r.assessDay)&&r.assessDay>=0&&r.assessDay<M.demoDays(s))row.assessDay=r.assessDay;}d.updated=M.stamp(s);return p;}
export function issues(s){const p=data(s).draft,out=[];if(p.goal.trim().length<8)out.push('우리 반 교육 목표를 8자 이상 적어 주세요.');if(p.support.trim().length<8)out.push('학생에게 필요한 지원 방법을 8자 이상 적어 주세요.');if(p.creative.some(r=>r.topic.trim().length<4))out.push('창체 세 영역의 활동을 구체적으로 적어 주세요.');if(p.rows.some(r=>r.goal.trim().length<4||!r.materials.trim()))out.push('과목별 목표와 준비물을 확인해 주세요.');return out;}
export function canWork(s,minutes){const slot=M.currentSlot(s);return ['classroom','research','staff'].includes(s.room)&&['morning','break','specialist','afternoon'].includes(slot.kind)&&s.minute+minutes<=Math.min(slot.end,1000)&&!M.movementBusy(s)&&!P.conflicts(s,s.day,s.minute,s.minute+minutes).length;}
export function confirm(s){if(s.academic&&!s.academic.acknowledged)return {error:'학교교육과정을 먼저 확인한 뒤 학급교육과정을 확정해 주세요.'};const d=data(s),problems=issues(s);if(problems.length)return {error:problems[0]};if(d.active&&JSON.stringify(d.active.plan)===JSON.stringify(d.draft))return {error:'확정한 계획과 같습니다. 변경할 내용을 먼저 수정해 주세요.'};if(!canWork(s,20))return {error:'교실·교사연구실·교무실에서 수업과 약속이 없는 20분을 확보해 주세요.'};M.advance(s,20);const record={number:(d.active?.number||0)+1,day:s.day,date:M.stamp(s),late:s.day>deadline(s),plan:structuredClone(d.draft)};d.active=record;d.revisions.unshift(record);d.revisions=d.revisions.slice(0,10);M.addMessage(s,'grade','나',`학급교육과정 ${record.number}차 계획을 공유합니다. 우리 반 목표: ${record.plan.goal}`,{senderId:'teacher',plannerScanned:true});M.addMessage(s,'all','한정우 교감',`학급교육과정 ${record.number}차 계획을 접수했습니다. ${record.late?'3월 이후 보완 제출로 기록했습니다. ':''}실제 수업과 학생 반응을 살피며 변경한 내용도 남겨 주세요.`,{senderId:'principal',plannerScanned:true});M.log(s,'학급교육과정 '+record.number+'차 확정'+(record.late?' · 기한 후 보완':''));sync(s);return {ok:true};}
export function row(s,subject){return data(s).active?.plan.rows.find(r=>r.subject===subject)||null;}
export function exportDocument(s){const d=data(s);if(!d.active)return null;const f=PC.createFile(s,'plan');if(!f)return null;const a=d.active;f.title=s.config.grade+'학년 학급교육과정 '+a.number+'차';f.body=`${M.REGIONS[s.config.region].school}\n${f.title}\n담임: ${s.config.teacherName}\n확정: ${a.date}\n\n우리 반 목표: ${a.plan.goal}\n중점: ${FOCUS[a.plan.focus]}\n학생 지원: ${a.plan.support}\n\n교과별 운영\n`+a.plan.rows.map(r=>`${r.subject}: ${r.goal}\n방법: ${C.methods(r.subject,true).find(m=>m.id===r.method).name} / 공간: ${M.ROOMS[r.room].name}\n준비물: ${r.materials}\n평가: ${r.evidence} / ${M.dateLabel({day:r.assessDay})}`).join('\n\n')+'\n\n창체\n'+a.plan.creative.map(c=>c.area+': '+c.topic).join('\n')+'\n\n학교 기본 시간표를 바탕으로 운영하며 창체와 연계한 활동을 중복 시수로 계산하지 않음.';return f;}
export function ledger(s){const out=Object.fromEntries(allSubjects(s).map(subject=>[subject,{subject,base:0,planned:0,due:0,actual:0,missed:[]}])),seen=new Set();for(let day=s.academic?.start||0;day<M.demoDays(s);day++){if(!A.schoolDay(s,day))continue;for(const slot of A.plannedSchedule(s,day))if(out[slot.subject])out[slot.subject].base++;for(const slot of M.todaySchedule({...s,day,...(s.academic?{academic:{...s.academic,phase:'term'}}:{})})){if(slot.credit===false)continue;const r=out[slot.subject];if(!r)continue;r.planned++;if(day<s.day||day===s.day&&slot.end<=s.minute){r.due++;if(!s.lessonResults.some(x=>x.day===day&&x.period===slot.period&&x.subject===slot.subject))r.missed.push({day,period:slot.period});}}}for(const result of s.lessonResults){const key=result.day+':'+result.period;if(out[result.subject]&&!seen.has(key)){out[result.subject].actual++;seen.add(key);}}return Object.values(out);}
export function planCatchup(s,subject){const d=data(s);if(d.catchups.length>=600)return {error:'보완 계획 기록이 가득 찼습니다. 기존 계획을 먼저 확인해 주세요.'};if(!d.active)return {error:'학급교육과정을 먼저 확정해 주세요.'};const missed=ledger(s).find(r=>r.subject===subject)?.missed.find(x=>!d.catchups.some(c=>c.subject===subject&&c.source.day===x.day&&c.source.period===x.period&&c.status!=='missed'));if(!missed)return {error:'새로 보완할 미실시 차시가 없습니다.'};if(!canWork(s,5))return {error:'수업·약속과 겹치지 않는 준비 시간 5분이 필요합니다.'};let target;for(let day=s.day;day<M.demoDays(s)&&!target;day++){const slot=M.todaySchedule({...s,day,...(s.academic?{academic:{...s.academic,phase:'term'}}:{})}).find(x=>!x.specialist&&x.subject===subject&&(day>s.day||x.start>=s.minute+5)&&!d.catchups.some(c=>c.target.day===day&&c.target.period===x.period));if(slot)target={day,period:slot.period};}if(!target)return {error:'남은 시간표에 같은 과목의 차시가 없습니다. 학년 협의에서 다음 계획을 확인해 주세요.'};M.advance(s,5);const c={subject,source:missed,target,status:'planned',goal:row(s,subject).goal,created:M.stamp(s)};d.catchups.push(c);M.log(s,subject+' 핵심 목표를 '+M.dateLabel({day:target.day})+' '+target.period+'교시에 다시 다루기로 계획');return {ok:true,target};}
export function valid(s){const d=s.classCurriculum;if(d==null)return true;const obj=v=>v&&typeof v==='object'&&!Array.isArray(v),str=(v,n)=>typeof v==='string'&&v.length<=n;const plan=p=>obj(p)&&str(p.goal,300)&&str(p.support,500)&&Object.hasOwn(FOCUS,p.focus)&&Array.isArray(p.rows)&&p.rows.length===allSubjects(s).length&&allSubjects(s).every(subject=>p.rows.filter(r=>r.subject===subject).length===1)&&p.rows.every(r=>str(r.goal,300)&&str(r.materials,300)&&C.subjectRooms(r.subject).includes(r.room)&&C.methods(r.subject,true).some(m=>m.id===r.method)&&EVIDENCE.includes(r.evidence)&&Number.isInteger(r.assessDay)&&r.assessDay>=0&&r.assessDay<M.demoDays(s))&&Array.isArray(p.creative)&&p.creative.length===3&&AREAS.every(area=>p.creative.filter(c=>c.area===area&&str(c.topic,180)).length===1);const version=v=>obj(v)&&Number.isInteger(v.number)&&v.number>0&&Number.isInteger(v.day)&&v.day>=0&&v.day<M.demoDays(s)&&str(v.date,100)&&typeof v.late==='boolean'&&plan(v.plan);const point=p=>obj(p)&&Number.isInteger(p.day)&&p.day>=0&&p.day<M.demoDays(s)&&Number.isInteger(p.period)&&p.period>=1&&p.period<=6;return obj(d)&&d.schema===1&&plan(d.draft)&&(d.active===null||version(d.active))&&Array.isArray(d.revisions)&&d.revisions.length<=10&&d.revisions.every(version)&&obj(d.notified)&&Array.isArray(d.catchups)&&d.catchups.length<=600&&d.catchups.every(c=>allSubjects(s).includes(c.subject)&&point(c.source)&&point(c.target)&&['planned','done','missed'].includes(c.status)&&str(c.goal,300)&&str(c.created,100));}
